PU: 224 \\u044f\\u0434\\u0440\\u0430 (`nproc`).\\n- **\\u0414\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442\\u043e\\u0432 \\u043d\\u0435\\u0442**: \\u043f\\u043e\\u0438\\u0441\\u043a \\u043f\\u043e \\u0444\\u0430\\u0439\\u043b\\u043e\\u0432\\u043e\\u0439 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0435 (ETT/traffic/weather-\\u0438\\u043c\\u0435\\u043d\\u0430) \\u0434\\u0430\\u043b \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u043b\\u043e\\u0436\\u043d\\u044b\\u0435 \\u0441\\u0438\\u0442\\u0435\\u043c\\u043d\\u044b\\u0435 \\u0441\\u043e\\u0432\\u043f\\u0430\\u0434\\u0435\\u043d\\u0438\\u044f. `datasets: []` \\u0432 \\u043e\\u043f\\u0438\\u0441\\u0430\\u043d\\u0438\\u0438 \\u043e\\u043a\\u0440\\u0443\\u0436\\u0435\\u043d\\u0438\\u044f \\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0430\\u0435\\u0442\\u0441\\u044f.\\n\\n\\u0412\\u044b\\u0432\\u043e\\u0434: \\u0432 \\u042d\\u0422\\u041e\\u041c \\u043e\\u043a\\u0440\\u0443\\u0436\\u0435\\u043d\\u0438\\u0438 \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u0435 \\u043d\\u0435\\u0432\\u043e\\u0437\\u043c\\u043e\\u0436\\u043d\\u043e \\u0434\\u0430\\u0436\\u0435 \\u0432 \\u043f\\u0440\\u0438\\u043d\\u0446\\u0438\\u043f\\u0435 (\\u043d\\u0435\\u043b\\u044c\\u0437\\u044f \\u043f\\u043e\\u0441\\u0442\\u0430\\u0432\\u0438\\u0442\\u044c \\u043d\\u0438 torch, \\u043d\\u0438 \\u0434\\u0430\\u043d\\u043d\\u044b\\u0435). \\u042d\\u0442\\u043e design-only \\u0437\\u0430\\u0434\\u0430\\u0447\\u0430, \\u0438 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d \\u043d\\u0438\\u0436\\u0435 \\u0440\\u0430\\u0441\\u0441\\u0447\\u0438\\u0442\\u0430\\u043d \\u043d\\u0430 \\u0432\\u043d\\u0435\\u0448\\u043d\\u0435\\u0435 \\u043e\\u043a\\u0440\\u0443\\u0436\\u0435\\u043d\\u0438\\u0435 \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u044f (GPU + torch + \\u0437\\u0430\\u0440\\u0430\\u043d\\u0435\\u0435 \\u0441\\u043a\\u0430\\u0447\\u0430\\u043d\\u043d\\u044b\\u0435 CSV).\\n\\n## 2. \\u041f\\u043e\\u0434\\u0445\\u043e\\u0434 \\u043a \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0443 \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0438\\u043c\\u0435\\u043d\\u0442\\u0430\\n\\n### \\u0410. \\u041f\\u043e\\u043d\\u0438\\u043c\\u0430\\u043d\\u0438\\u0435 \\u043a\\u043b\\u044e\\u0447\\u0435\\u0432\\u043e\\u0433\\u043e \\u043c\\u0435\\u0445\\u0430\\u043d\\u0438\\u0437\\u043c\\u0430 CycleNet (Liang et al., ICLR 2023)\\n\\n- **\\u041f\\u0430\\u0442\\u0442\\u0435\\u0440\\u043d-\\u0431\\u0430\\u043d\\u043a (cycle-agnostic residual pattern bank):** \\u0442\\u0430\\u0431\\u043b\\u0438\\u0446\\u0430 \\u043f\\u0430\\u0440\\u0430\\u043c\\u0435\\u0442\\u0440\\u043e\\u0432/\\u0431\\u0443\\u0444\\u0435\\u0440 \\u0440\\u0430\\u0437\\u043c\\u0435\\u0440\\u0430 L\\u00d7d (L \\u2014 \\u0434\\u043b\\u0438\\u043d\\u0430 \\u0446\\u0438\\u043a\\u043b\\u0430), \\u0445\\u0440\\u0430\\u043d\\u044f\\u0449\\u0430\\u044f residual-\\u043f\\u0430\\u0442\\u0442\\u0435\\u0440\\u043d\\u044b \\u043f\\u043e \\u0444\\u0430\\u0437\\u0430\\u043c \\u0446\\u0438\\u043a\\u043b\\u0430. \\u0418\\u0434\\u0435\\u044f \\u0432 \\u0442\\u043e\\u043c, \\u0447\\u0442\\u043e \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\u0438\\u0447\\u0435\\u0441\\u043a\\u0430\\u044f \\u043a\\u043e\\u043c\\u043f\\u043e\\u043d\\u0435\\u043d\\u0442\\u0430 \\u2014 \\u044d\\u0442\\u043e \\u043d\\u0435 \\u00ab\\u0441\\u0438\\u043d\\u0443\\u0441\\u043e\\u0438\\u0434\\u0430\\u00bb, \\u0430 \\u043f\\u0440\\u043e\\u0438\\u0437\\u0432\\u043e\\u043b\\u044c\\u043d\\u0430\\u044f \\u0444\\u043e\\u0440\\u043c\\u0430, \\u043f\\u043e\\u0432\\u0442\\u043e\\u0440\\u044f\\u044e\\u0449\\u0430\\u044f\\u0441\\u044f \\u0441 \\u0446\\u0438\\u043a\\u043b\\u043e\\u043c; \\u043c\\u043e\\u0434\\u0435\\u043b\\u044c \\u0443\\u0447\\u0438\\u0442 \\u0438\\u043c\\u0435\\u043d\\u043d\\u043e \\u0435\\u0451.\\n- **\\u0410\\u0433\\u0440\\u0435\\u0433\\u0430\\u0446\\u0438\\u044f \\u043f\\u043e \\u0444\\u0430\\u0437\\u0435:** \\u0434\\u043b\\u044f \\u0448\\u0430\\u0433\\u0430 t \\u0444\\u0430\\u0437\\u0430 = t mod L; \\u0432\\u043a\\u043b\\u0430\\u0434 \\u043a\\u0430\\u0436\\u0434\\u043e\\u0439 \\u0444\\u0430\\u0437\\u044b \\u0443\\u0441\\u0440\\u0435\\u0434\\u043d\\u044f\\u0435\\u0442\\u0441\\u044f/EMA-\\u043e\\u0431\\u043d\\u043e\\u0432\\u043b\\u044f\\u0435\\u0442\\u0441\\u044f \\u043f\\u043e \\u0432\\u0441\\u0435\\u043c \\u0446\\u0438\\u043a\\u043b\\u0430\\u043c \\u043e\\u0431\\u0443\\u0447\\u0430\\u044e\\u0449\\u0435\\u0439 \\u0432\\u044b\\u0431\\u043e\\u0440\\u043a\\u0438, \\u0447\\u0442\\u043e \\u043f\\u043e\\u0434\\u0430\\u0432\\u043b\\u044f\\u0435\\u0442 \\u0448\\u0443\\u043c \\u0438 \\u043d\\u0435\\u0440\\u0435\\u0433\\u0443\\u043b\\u044f\\u0440\\u043d\\u043e\\u0441\\u0442\\u044c \\u043e\\u0442\\u0434\\u0435\\u043b\\u044c\\u043d\\u044b\\u0445 \\u043d\\u0430\\u0431\\u043b\\u044e\\u0434\\u0435\\u043d\\u0438\\u0439.\\n- **\\u0413\\u0430\\u0439\\u0434\\u044f\\u0449\\u0435\\u0435 (periodically induced) loss:** \\u0434\\u043e\\u043f\\u043e\\u043b\\u043d\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u044b\\u0439 \\u0447\\u043b\\u0435\\u043d, \\u043f\\u0440\\u0438\\u0442\\u044f\\u0433\\u0438\\u0432\\u0430\\u044e\\u0449\\u0438\\u0439 \\u043e\\u0446\\u0435\\u043d\\u043a\\u0443 residual-\\u043f\\u0430\\u0442\\u0442\\u0435\\u0440\\u043d\\u0430 \\u043e\\u0442\\u0434\\u0435\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u043e\\u043a\\u043d\\u0430 \\u043a \\u0430\\u0433\\u0440\\u0435\\u0433\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u043e\\u043c\\u0443 \\u043f\\u0430\\u0442\\u0442\\u0435\\u0440\\u043d\\u0443 \\u0442\\u043e\\u0439 \\u0436\\u0435 \\u0444\\u0430\\u0437\\u044b \\u2014 \\u0431\\u0435\\u0437 \\u043d\\u0435\\u0433\\u043e \\u0430\\u0433\\u0440\\u0435\\u0433\\u0430\\u0446\\u0438\\u044f \\u0440\\u0430\\u0437\\u043c\\u044b\\u0432\\u0430\\u0435\\u0442\\u0441\\u044f \\u0448\\u0443\\u043c\\u043e\\u043c/\\u043f\\u0440\\u043e\\u043f\\u0443\\u0441\\u043a\\u0430\\u043c\\u0438. \\u042d\\u0442\\u043e \\u0442\\u043e, \\u0447\\u0442\\u043e \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0435\\u0440\\u0441\\u043a\\u0438 \\u043d\\u0430\\u0434\\u043e \\u0430\\u0431\\u043b\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c \\u043e\\u0442\\u0434\\u0435\\u043b\\u044c\\u043d\\u043e.\\n- **\\u041f\\u0440\\u043e\\u0433\\u043d\\u043e\\u0437\\u043d\\u0430\\u044f \\u0447\\u0430\\u0441\\u0442\\u044c \\u043d\\u0430\\u043c\\u0435\\u0440\\u0435\\u043d\\u043d\\u043e \\u043f\\u0440\\u043e\\u0441\\u0442\\u0430\\u044f:** MLP \\u0431\\u0435\\u0437 attention; \\u0432\\u0445\\u043e\\u0434 \\u2014 flatten \\u043e\\u043a\\u043d\\u0430 lookback + \\u0430\\u0433\\u0440\\u0435\\u0433\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0439 \\u043f\\u0430\\u0442\\u0442\\u0435\\u0440\\u043d \\u043d\\u0430 \\u0446\\u0435\\u043b\\u0435\\u0432\\u044b\\u0435 \\u0444\\u0430\\u0437\\u044b; \\u0444\\u0430\\u0437\\u0430 \\u043a\\u043e\\u0434\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f \\u0424\\u0443\\u0440\\u044c\\u0435-\\u043f\\u0440\\u0438\\u0437\\u043d\\u0430\\u043a\\u0430\\u043c\\u0438 sin/cos(2\\u03c0k\\u00b7i/L) \\u0434\\u043b\\u044f k=1..K \\u0433\\u0430\\u0440\\u043c\\u043e\\u043d\\u0438\\u043a. \\u041f\\u0440\\u043e\\u0438\\u0437\\u0432\\u043e\\u043b\\u044c\\u043d\\u0430\\u044f \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\u0438\\u0447\\u043d\\u043e\\u0441\\u0442\\u044c L \\u0432\\u0445\\u043e\\u0434\\u0438\\u0442 \\u043a\\u0430\\u043a \\u0433\\u0438\\u043f\\u0435\\u0440\\u043f\\u0430\\u0440\\u0430\\u043c\\u0435\\u0442\\u0440, \\u0430 \\u043d\\u0435 \\u0430\\u0440\\u0445\\u0438\\u0442\\u0435\\u043a\\u0442\\u0443\\u0440\\u043d\\u043e\\u0435 \\u043e\\u0433\\u0440\\u0430\\u043d\\u0438\\u0447\\u0435\\u043d\\u0438\\u0435; \\u043d\\u0435\\u0441\\u043a\\u043e\\u043b\\u044c\\u043a\\u043e \\u0433\\u0430\\u0440\\u043c\\u043e\\u043d\\u0438\\u043a/\\u043d\\u0435\\u0441\\u043a\\u043e\\u043b\\u044c\\u043a\\u043e \\u0447\\u0430\\u0441\\u0442\\u043e\\u0442 \\u2014 \\u043b\\u0438\\u0431\\u043e K-\\u0433\\u0430\\u0440\\u043c\\u043e\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u043a\\u043e\\u0434 \\u0444\\u0430\\u0437\\u044b, \\u043b\\u0438\\u0431\\u043e \\u043e\\u0442\\u0434\\u0435\\u043b\\u044c\\u043d\\u044b\\u0439 \\u043f\\u0430\\u0442\\u0442\\u0435\\u0440\\u043d-\\u0431\\u0430\\u043d\\u043a \\u043d\\u0430 \\u043a\\u0430\\u0436\\u0434\\u0443\\u044e \\u0434\\u043e\\u043c\\u0438\\u043d\\u0438\\u0440\\u0443\\u044e\\u0449\\u0443\\u044e \\u0447\\u0430\\u0441\\u0442\\u043e\\u0442\\u0443 (\\u0434\\u043b\\u044f \\u043c\\u043d\\u043e\\u0433\\u043e\\u043a\\u0430\\u043d\\u0430\\u043b\\u044c\\u043d\\u044b\\u0445 \\u0434\\u0430\\u043d\\u043d\\u044b\\u0445 \\u0441 \\u0440\\u0430\\u0437\\u043d\\u044b\\u043c\\u0438 \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\u0430\\u043c\\u0438 \\u2014 per-channel L).\\n- \\u041a\\u0440\\u0438\\u0442\\u0438\\u0447\\u043d\\u043e \\u0434\\u043b\\u044f \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0430: CycleNet \\u043f\\u043e\\u0437\\u0438\\u0446\\u0438\\u043e\\u043d\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f \\u043a\\u0430\\u043a \\u0443\\u0441\\u0442\\u043e\\u0439\\u0447\\u0438\\u0432\\u044b\\u0439 \\u043a **\\u043d\\u0435\\u0440\\u0435\\u0433\\u0443\\u043b\\u044f\\u0440\\u043d\\u043e\\u0439 \\u0434\\u0438\\u0441\\u043a\\u0440\\u0435\\u0442\\u0438\\u0437\\u0430\\u0446\\u0438\\u0438 \\u0438 \\u043f\\u0440\\u043e\\u043f\\u0443\\u0441\\u043a\\u0430\\u043c** \\u2014 \\u044d\\u0442\\u043e \\u043d\\u0430\\u0434\\u043e \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u0438\\u0442\\u044c \\u043e\\u0442\\u0434\\u0435\\u043b\\u044c\\u043d\\u044b\\u043c \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0438\\u043c\\u0435\\u043d\\u0442\\u043e\\u043c, \\u0438\\u043d\\u0430\\u0447\\u0435 \\u043e\\u0441\\u0442\\u0430\\u0451\\u0442\\u0441\\u044f \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u00ab\\u0435\\u0449\\u0451 \\u043e\\u0434\\u043d\\u0430 \\u043b\\u0438\\u043d\\u0435\\u0439\\u043d\\u043e-MLP \\u043c\\u043e\\u0434\\u0435\\u043b\\u044c\\u00bb.\\n\\n### \\u0411. \\u0414\\u0430\\u043d\\u043d\\u044b\\u0435 \\u0438 \\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b\\n\\n- **\\u0411\\u0435\\u043d\\u0447\\u043c\\u0430\\u0440\\u043a\\u0438 \\u0441 \\u0432\\u044b\\u0440\\u0430\\u0436\\u0435\\u043d\\u043d\\u043e\\u0439 \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\u0438\\u043a\\u043e\\u0439:** ETTm1/ETTm2 (10 \\u043c\\u0438\\u043d, \\u0441\\u0443\\u0442\\u043e\\u0447\\u043d\\u044b\\u0439 \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434 L=144/288\\u2026 \\u0443\\u0442\\u043e\\u0447\\u043d\\u0438\\u0442\\u044c \\u043f\\u043e \\u0447\\u0430\\u0441\\u0442\\u043e\\u0442\\u0435), ETTh1/ETTh2 (\\u0447\\u0430\\u0441\\u043e\\u0432\\u043e\\u0439, \\u0441\\u0443\\u0442\\u043e\\u0447\\u043d\\u044b\\u0439 L=24, \\u043d\\u0435\\u0434\\u0435\\u043b\\u044c\\u043d\\u044b\\u0439 L=168), Weather, Traffic, Electricity (\\u043f\\u043e\\u0441\\u043b\\u0435\\u0434\\u043d\\u0438\\u0439 \\u2014 \\u043a\\u0430\\u043a \\u00ab\\u0436\\u0451\\u0441\\u0442\\u043a\\u0438\\u0439\\u00bb \\u0441 \\u043d\\u0435\\u0434\\u0435\\u043b\\u044c\\u043d\\u043e\\u0439 \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\u0438\\u043a\\u043e\\u0439). \\u041c\\u0438\\u043d\\u0438\\u043c\\u0430\\u043b\\u044c\\u043d\\u043e \\u0434\\u043e\\u0441\\u0442\\u0430\\u0442\\u043e\\u0447\\u043d\\u044b\\u0439 \\u043d\\u0430\\u0431\\u043e\\u0440: ETTm1, ETTh1, Weather, Traffic.\\n- **\\u0421\\u043f\\u043b\\u0438\\u0442\\u044b \\u2014 \\u0441\\u0442\\u0430\\u043d\\u0434\\u0430\\u0440\\u0442\\u043d\\u044b\\u0435 \\u0434\\u043b\\u044f long-horizon TSF** (Zeng et al./Wu et al.): ETTh \\u2014 12/4/4 \\u043c\\u0435\\u0441\\u044f\\u0446\\u0430 (7:1:2), ETTm \\u2014 34/4/5 \\u0434\\u043d\\u0435\\u0439, Weather/Traffic/Electricity \\u2014 7:1:2 \\u043f\\u043e \\u0432\\u0440\\u0435\\u043c\\u0435\\u043d\\u0438. \\u0422\\u043e\\u043b\\u044c\\u043a\\u043e forward-chaining, \\u0431\\u0435\\u0437 \\u0441\\u043b\\u0443\\u0447\\u0430\\u0439\\u043d\\u043e\\u0433\\u043e \\u043f\\u0435\\u0440\\u0435\\u043c\\u0435\\u0448\\u0438\\u0432\\u0430\\u043d\\u0438\\u044f \\u043e\\u043a\\u043e\\u043d \\u043c\\u0435\\u0436\\u0434\\u0443 \\u0441\\u043f\\u043b\\u0438\\u0442\\u0430\\u043c\\u0438.\\n- **\\u041f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b:** lookback 96 (\\u0430\\u043b\\u0441\\u043e 512 \\u0434\\u043b\\u044f \\u0441\\u043e\\u043f\\u043e\\u0441\\u0442\\u0430\\u0432\\u0438\\u043c\\u043e\\u0441\\u0442\\u0438 \\u0441 SOTA-\\u0442\\u0430\\u0431\\u043b\\u0438\\u0446\\u0430\\u043c\\u0438), horizons {96, 192, 336, 724}; \\u0441\\u043a\\u043e\\u043b\\u044c\\u0437z\\u0105ce \\u043e\\u043a\\u043d\\u0430; instance normalization (RevIN) \\u0441\\u043e \\u0441\\u0442\\u0430\\u043d\\u0434\\u0430\\u0440\\u0442\\u043d\\u044b\\u043c \\u0434\\u0435\\u043d\\u043e\\u0440\\u043c\\u0430\\u043b\\u0438\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435\\u043c \\u043d\\u0430 \\u0442\\u0435\\u0441\\u0442\\u0435; MSE/MAE \\u043d\\u0430 \\u043d\\u043e\\u0440\\u043c\\u0430\\u043b\\u0438\\u0437\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0445 \\u0434\\u0430\\u043d\\u043d\\u044b\\u0445; 2\\u20133 \\u0441\\u0438\\u0434\\u0430; \\u043c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0438 \\u043f\\u043e \\u043a\\u0430\\u0436\\u0434\\u043e\\u043c\\u0443 \\u0433\\u043e\\u0440\\u0438\\u0437\\u043e\\u043d\\u0442\\u0443 \\u043e\\u0442\\u0434\\u0435\\u043b\\u044c\\u043d\\u043e.\\n\\n### \\u0412. \\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c\\u043d\\u044b\\u0435 \\u0433\\u0440\\u0443\\u043f\\u043f\\u044b / \\u0431\\u0430\\u0437\\u043e\\u0432\\u044b\\u0435 \\u043b\\u0438\\u043d\\u0438\\u0438 (\\u043e\\u0431\\u044f\\u0437\\u0430\\u0442\\u0435\\u043b\\u044c\\u043d\\u044b\\u0439 \\u043c\\u0438\\u043d\\u0438\\u043c\\u0443\\u043c)\\n\\n1. **Naive repeat (\\u043f\\u043e\\u0441\\u043b\\u0435\\u0434\\u043d\\u0435\\u0435 \\u0437\\u043d\\u0430\\u0447\\u0435\\u043d\\u0438\\u0435)** \\u0438 **seasonal naive** (\\u0437\\u043d\\u0430\\u0447\\u0435\\u043d\\u0438\\u0435 \\u0440\\u043e\\u0432\\u043d\\u043e \\u043d\\u0430 L \\u043d\\u0430\\u0437\\u0430\\u0434) \\u2014 \\u043d\\u0438\\u0436\\u043d\\u044f\\u044f \\u0433\\u0440\\u0430\\u043d\\u0438\\u0446\\u0430; seasonal naive \\u043e\\u0441\\u043e\\u0431\\u0435\\u043d\\u043d\\u043e \\u0432\\u0430\\u0436\\u0435\\u043d: \\u043e\\u043d \\u0441\\u0430\\u043c \\u043f\\u043e \\u0441\\u0435\\u0431\\u0435 \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u0443\\u0435\\u0442 \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\u0438\\u0447\\u043d\\u043e\\u0441\\u0442\\u044c \\u0438 \\u043f\\u043e\\u043a\\u0430\\u0437\\u044b\\u0432\\u0430\\u0435\\u0442, \\u0441\\u043a\\u043e\\u043b\\u044c\\u043a\\u043e \\u0432\\u043e\\u043e\\u0431\\u0449\\u0435 \\u0434\\u0430\\u0451\\u0442 \\u00ab\\u0437\\u043d\\u0430\\u0442\\u044c \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\u00bb.\\n2. **DLinear** \\u2014 \\u0441\\u0438\\u043b\\u044c\\u043d\\u0430\\u044f \\u043b\\u0438\\u043d\\u0435\\u0439\\u043d\\u0430\\u044f \\u0431\\u0430\\u0437\\u043e\\u0432\\u0430\\u044f \\u043b\\u0438\\u043d\\u0438\\u044f \\u0431\\u0435\\u0437 \\u044f\\u0432\\u043d\\u043e\\u0439 \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0439 \\u043a\\u043e\\u043c\\u043f\\u043e\\u043d\\u0435\\u043d\\u0442\\u044b.\\n3. **\\u0422\\u0440\\u0430\\u043d\\u0441\\u0444\\u043e\\u0440\\u043c\\u0435\\u0440-\\u0431\\u0430\\u0437\\u043e\\u0432\\u0430\\u044f \\u043b\\u0438\\u043d\\u0438\\u044f** \\u2014 PatchTST (\\u0441\\u043e\\u0432\\u0440\\u0435\\u043c\\u0435\\u043d\\u043d\\u044b\\u0439 \\u0441\\u0438\\u043b\\u044c\\u043d\\u044b\\u0439) \\u0438/\\u0438\\u043b\\u0438 Informer/Autoformer (\\u0434\\u043b\\u044f \\u0441\\u0432\\u044f\\u0437\\u0438 \\u0441 \\u043e\\u0440\\u0438\\u0433\\u0438\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0439 \\u0442\\u0430\\u0431\\u043b\\u0438\\u0446\\u0435\\u0439 CycleNet).\\n4. **\\u0410\\u0431\\u043b\\u044f\\u0446\\u0438\\u0438 CycleNet** (\\u044f\\u0434\\u0440\\u043e \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u043a\\u0438 \\u0433\\u0438\\u043f\\u043e\\u0442\\u0435\\u0437\\u044b): (\\u0430) \\u0431\\u0435\\u0437 \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438-\\u0433\\u0430\\u0439\\u0434\\u044f\\u0449\\u0435\\u0433\\u043e loss; (\\u0431) \\u0431\\u0435\\u0437 \\u043f\\u0430\\u0442\\u0442\\u0435\\u0440\\u043d-\\u0431\\u0430\\u043d\\u043a\\u0430 (\\u0442\\u043e\\u0442 \\u0436\\u0435 MLP, \\u043d\\u043e \\u0444\\u0430\\u0437\\u0430 \\u043d\\u0435 \\u043f\\u043e\\u0434\\u0430\\u0451\\u0442\\u0441\\u044f); (\\u0432) \\u0431\\u0435\\u0437 \\u0424\\u0443\\u0440\\u044c\\u0435-\\u043a\\u043e\\u0434\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f \\u0444\\u0430\\u0437\\u044b (learned embedding \\u0432\\u043c\\u0435\\u0441\\u0442\\u043e sin/cos); (\\u0433) \\u0431\\u0435\\u0437 \\u0430\\u0433\\u0440\\u0435\\u0433\\u0430\\u0446\\u0438\\u0438 \\u043f\\u043e \\u0444\\u0430\\u0437\\u0435 (bank \\u0447\\u0438\\u0442\\u0430\\u0435\\u0442\\u0441\\u044f, \\u043d\\u043e \\u043d\\u0435 \\u0443\\u0441\\u0440\\u0435\\u0434\\u043d\\u044f\\u0435\\u0442\\u0441\\u044f \\u043f\\u043e \\u0446\\u0438\\u043a\\u043b\\u0430\\u043c).\\n\\n### \\u0413. \\u041f\\u043b\\u0430\\u043d \\u0430\\u043d\\u0430\\u043b\\u0438\\u0437\\u0430: \\u043a\\u0430\\u043a \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u0438\\u0442\\u044c, \\u0447\\u0442\\u043e \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\u0438\\u0447\\u0435\\u0441\\u043a\\u0430\\u044f \\u043a\\u043e\\u043c\\u043f\\u043e\\u043d\\u0435\\u043d\\u0442\\u0430 \\u0440\\u0435\\u0430\\u043b\\u044c\\u043d\\u043e \\u0434\\u0430\\u0451\\u0442 \\u044d\\u0444\\u0444\\u0435\\u043a\\u0442\\n\\n- \\u0413\\u043b\\u0430\\u0432\\u043d\\u0430\\u044f \\u0442\\u0430\\u0431\\u043b\\u0438\\u0446\\u0430 MSE/MAE \\u043f\\u043e \\u0434\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442\\u00d7\\u0433\\u043e\\u0440\\u0438\\u0437\\u043e\\u043d\\u0442, \\u0432\\u0441\\u0435 \\u043c\\u0435\\u0442\\u043e\\u0434\\u044b, \\u0441\\u0440\\u0435\\u0434\\u043d\\u0435\\u0435\\u00b1std \\u043f\\u043e \\u0441\\u0438\\u0434\\u0430\\u043c.\\n- **\\u0422\\u0435\\u0441\\u0442 \\u00ab\\u043f\\u0440\\u0438\\u0447\\u0438\\u043d\\u043d\\u043e\\u0441\\u0442\\u0438\\u00bb \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\u0438\\u043a\\u0438:** sensitivity \\u043f\\u043e L \\u2014 \\u043f\\u0440\\u0430\\u0432\\u0438\\u043b\\u044c\\u043d\\u0430\\u044f L vs L\\u00b11/L\\u00b12 vs \\u043d\\u0430\\u043c\\u0435\\u0440\\u0435\\u043d\\u043d\\u043e \\u043d\\u0435\\u0432\\u0435\\u0440\\u043d\\u0430\\u044f L (\\u043d\\u0430\\u043f\\u0440\\u0438\\u043c\\u0435\\u0440, \\u043d\\u0435\\u0434\\u0435\\u043b\\u044c\\u043d\\u0430\\u044f \\u0432\\u043c\\u0435\\u0441\\u0442\\u043e \\u0441\\u0443\\u0442\\u043e\\u0447\\u043d\\u043e\\u0439). \\u0415\\u0441\\u043b\\u0438 \\u0432\\u044b\\u0438\\u0433\\u0440\\u044b\\u0448 \\u0438\\u0441\\u0447\\u0435\\u0437\\u0430\\u0435\\u0442 \\u043f\\u0440\\u0438 \\u0441\\u0431\\u0438\\u0442\\u043e\\u0439 L \\u2014 \\u044d\\u0444\\u0444\\u0435\\u043a\\u0442 \\u0434\\u0435\\u0439\\u0441\\u0442\\u0432\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e \\u043e\\u0442 \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0439 \\u043a\\u043e\\u043c\\u043f\\u043e\\u043d\\u0435\\u043d\\u0442\\u044b, \\u0430 \\u043d\\u0435 \\u043e\\u0442 \\u0451\\u043c\\u043a\\u043e\\u0441\\u0442\\u0438 MLP.\\n- **\\u0420\\u0430\\u0437\\u043b\\u043e\\u0436\\u0435\\u043d\\u0438\\u0435 \\u043e\\u0448\\u0438\\u0431\\u043a\\u0438:** \\u043f\\u0440\\u043e\\u0433\\u043d\\u043e\\u0437 = periodic-\\u0432\\u043a\\u043b\\u0430\\u0434 + MLP-residual; \\u043f\\u043e\\u0441\\u0447\\u0438\\u0442\\u0430\\u0442\\u044c \\u0434\\u043e\\u043b\\u044e MSE, \\u043e\\u0431\\u044a\\u044f\\u0441\\u043d\\u0451\\u043d\\u043d\\u0443\\u044e periodic-\\u0432\\u043a\\u043b\\u0430\\u0434\\u043e\\u043c (\\u0441\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u0435 \\u0441 \\u043c\\u043e\\u0434\\u0435\\u043b\\u044c\\u044e \\u043f\\u0440\\u0438 \\u043e\\u0431\\u043d\\u0443\\u043b\\u0451\\u043d\\u043d\\u043e\\u043c \\u0431\\u0430\\u043d\\u043a\\u0435).\\n- **\\u0423\\u0441\\u0442\\u043e\\u0439\\u0447\\u0438\\u0432\\u043e\\u0441\\u0442\\u044c \\u043a \\u043f\\u0440\\u043e\\u043f\\u0443\\u0441\\u043a\\u0430\\u043c/\\u043d\\u0435\\u0440\\u0435\\u0433\\u0443\\u043b\\u044f\\u0440\\u043d\\u043e\\u0441\\u0442\\u0438** (motivating claim \\u0441\\u0442\\u0430\\u0442\\u044c\\u0438): \\u043d\\u0430 \\u0441\\u0438\\u043d\\u0442\\u0435\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438 \\u043f\\u0440\\u043e\\u0440\\u0435\\u0436\\u0435\\u043d\\u043d\\u044b\\u0445 ETTm/Traffic (10\\u201350% \\u043f\\u0440\\u043e\\u043f\\u0443\\u0441\\u043a\\u043e\\u0432) \\u0441\\u0440\\u0430\\u0432\\u043d\\u0438\\u0442\\u044c CycleNet \\u0441 seasonal naive \\u0438 PatchTST; \\u043e\\u0436\\u0438\\u0434\\u0430\\u0435\\u043c\\u044b\\u0439 \\u0441\\u0438\\u0433\\u043d\\u0430\\u043b \\u2014 \\u0434\\u0435\\u0433\\u0440\\u0430\\u0434\\u0430\\u0446\\u0438\\u044f \\u0431\\u0430\\u0437\\u043e\\u0432\\u044b\\u0445 \\u043b\\u0438\\u043d\\u0438\\u0439 \\u0431\\u044b\\u0441\\u0442\\u0440\\u0435\\u0435.\\n- \\u0412\\u0438\\u0437\\u0443\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f: \\u0432\\u044b\\u0443\\u0447\\u0435\\u043d\\u043d\\u044b\\u0439 \\u043f\\u0430\\u0442\\u0442\\u0435\\u0440\\u043d-\\u0431\\u0430\\u043d\\u043a \\u043f\\u0440\\u043e\\u0442\\u0438\\u0432 \\u044d\\u043c\\u043f\\u0438\\u0440\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0433\\u043e cycle-average \\u0434\\u0430\\u043d\\u043d\\u044b\\u0445 \\u2014 qualitative check \\u043e\\u0441\\u043c\\u044b\\u0441\\u043b\\u0435\\u043d\\u043d\\u043e\\u0441\\u0442\\u0438.\\n- \\u0421\\u0442\\u0430\\u0442\\u0438\\u0441\\u0442\\u0438\\u043a\\u0430: \\u043f\\u043e 2\\u20133 \\u0441\\u0438\\u0434\\u0430\\u043c, \\u0434\\u043e\\u0432\\u0435\\u0440\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u044b\\u0435 \\u0438\\u043d\\u0442\\u0435\\u0440\\u0432\\u0430\\u043b\\u044b \\u043f\\u043e \\u0441\\u0438\\u0434\\u0430\\u043c; \\u0431\\u0435\\u0437 \\u0442\\u0435\\u0441\\u0442\\u043e\\u0432\\u043e\\u0439 \\u043f\\u043e\\u0434\\u0433\\u043e\\u043d\\u043a\\u0438 \\u0433\\u0438\\u043f\\u0435\\u0440\\u043f\\u0430\\u0440\\u0430\\u043c\\u0435\\u0442\\u0440\\u043e\\u0432 (\\u0432\\u044b\\u0431\\u043e\\u0440 \\u043f\\u043e \\u0432\\u0430\\u043b\\u0438\\u0434\\u0430\\u0446\\u0438\\u0438).\\n\\n### \\u0414. Feasibility \\u0432 \\u0434\\u0430\\u043d\\u043d\\u043e\\u043c \\u043e\\u043a\\u0440\\u0443\\u0436\\u0435\\u043d\\u0438\\u0438 \\u2014 \\u0447\\u0435\\u0441\\u0442\\u043d\\u0430\\u044f \\u043e\\u0446\\u0435\\u043d\\u043a\\u0430\\n\\n- **\\u0417\\u0434\\u0435\\u0441\\u044c \\u043d\\u0435\\u0432\\u043e\\u0437\\u043c\\u043e\\u0436\\u043d\\u043e \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u0438\\u0442\\u044c \\u043d\\u0438\\u0447\\u0435\\u0433\\u043e:** \\u043d\\u0435\\u0442 \\u043f\\u0430\\u043a\\u0435\\u0442\\u043e\\u0432, \\u043d\\u0435\\u0442 \\u0441\\u0435\\u0442\\u0438 \\u0434\\u043b\\u044f \\u0438\\u0445 \\u0443\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043a\\u0438, \\u043d\\u0435\\u0442 \\u0434\\u0430\\u043d\\u043d\\u044b\\u0445, \\u043d\\u0435\\u0442 GPU. \\u0427\\u0438\\u0441\\u0442\\u044b\\u0439 stdlib Python 3.14 \\u0434\\u043b\\u044f \\u043e\\u0431\\u0443\\u0447\\u0435\\u043d\\u0438\\u044f \\u043d\\u0435\\u0439\\u0440\\u043e\\u0441\\u0435\\u0442\\u0438 \\u043d\\u0435\\u0440\\u0435\\u0430\\u043b\\u0438\\u0441\\u0442\\u0438\\u0447\\u0435\\u043d (\\u0434\\u0430\\u0436\\u0435 numpy \\u043e\\u0442\\u0441\\u0443\\u0442\\u0441\\u0442\\u0432\\u0443\\u0435\\u0442), CPU-\\u043e\\u0431\\u0443\\u0447\\u0435\\u043d\\u0438\\u0435 Traffic/Electricity \\u0431\\u044b\\u043b\\u043e \\u0431\\u044b \\u043d\\u0435\\u0434\\u043e\\u0441\\u0442\\u0443\\u043f\\u043d\\u043e \\u0438 \\u043d\\u0430 GPU-\\u043c\\u0430\\u0448\\u0438\\u043d\\u0435 \\u0431\\u0435\\u0437 \\u0431\\u044e\\u0434\\u0436\\u0435\\u0442\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f.\\n- \\u0421\\u043b\\u0435\\u0434\\u0441\\u0442\\u0432\\u0438\\u0435 \\u0434\\u043b\\u044f \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0430: \\u043e\\u043d \\u0434\\u043e\\u043b\\u0436\\u0435\\u043d \\u0431\\u044b\\u0442\\u044c \\u0441\\u0430\\u043c\\u043e\\u0434\\u043e\\u0441\\u0442\\u0430\\u0442\\u043e\\u0447\\u043d\\u044b\\u043c \\u0441\\u043f\\u0435\\u0446\\u0438\\u0444\\u0438\\u043a\\u0430\\u0446\\u0438\\u043e\\u043d\\u043d\\u044b\\u043c \\u0434\\u043e\\u043a\\u0443\\u043c\\u0435\\u043d\\u0442\\u043e\\u043c (\\u0433\\u0438\\u043f\\u0435\\u0440\\u043f\\u0430\\u0440\\u0430\\u043c\\u0435\\u0442\\u0440\\u044b, \\u0441\\u043f\\u043b\\u0438\\u0442\\u044b, \\u0430\\u0431\\u043b\\u044f\\u0446\\u0438\\u0438) \\u0434\\u043b\\u044f \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u044f \\u0432\\u043d\\u0435 \\u044d\\u0442\\u043e\\u0433\\u043e sandbox; \\u0437\\u0434\\u0435\\u0441\\u044c \\u0432\\u043e\\u0437\\u043c\\u043e\\u0436\\u043d\\u044b \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u00abfeasible checks\\u00bb \\u0431\\u0435\\u0437 \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u044f \\u043c\\u043e\\u0434\\u0435\\u043b\\u0438 \\u2014 \\u0441\\u0432\\u0435\\u0440\\u043a\\u0430 \\u0444\\u043e\\u0440\\u043c\\u0430\\u0442\\u0430 \\u0434\\u0430\\u043d\\u043d\\u044b\\u0445, \\u043f\\u043e\\u0434\\u0441\\u0447\\u0451\\u0442 L \\u0438\\u0437 \\u0442\\u0430\\u0439\\u043c\\u0441\\u0442\\u0430\\u043c\\u043f\\u043e\\u0432, \\u043e\\u0446\\u0435\\u043d\\u043a\\u0430 \\u043f\\u0430\\u043c\\u044f\\u0442\\u0438/\\u0432\\u0440\\u0435\\u043c\\u0435\\u043d\\u0438 \\u043f\\u043e \\u0444\\u043e\\u0440\\u043c\\u0443\\u043b\\u0430\\u043c.\\n- \\u0415\\u0441\\u043b\\u0438 \\u043f\\u043e\\u0437\\u0436\\u0435 \\u043f\\u043e\\u043d\\u0430\\u0434\\u043e\\u0431\\u0438\\u0442\\u0441\\u044f \\u0445\\u043e\\u0442\\u044c \\u043a\\u0430\\u043a\\u043e\\u0439-\\u0442\\u043e \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u044f\\u0435\\u043c\\u044b\\u0439 \\u0430\\u0440\\u0442\\u0435\\u0444\\u0430\\u043a\\u0442 \\u0437\\u0434\\u0435\\u0441\\u044c: \\u0435\\u0434\\u0438\\u043d\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u0439 \\u0432\\u0430\\u0440\\u0438\\u0430\\u043d\\u0442 \\u2014 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d-\\u0432\\u0430\\u043b\\u0438\\u0434\\u0430\\u0446\\u0438\\u044f \\u043d\\u0430 \\u043a\\u0440\\u043e\\u0448\\u0435\\u0447\\u043d\\u043e\\u043c \\u0441\\u0438\\u043d\\u0442\\u0435\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u043c \\u0440\\u044f\\u0434\\u0443, \\u0441\\u0433\\u0435\\u043d\\u0435\\u0440\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u043e\\u043c stdlib-\\u043e\\u043c (`random`, `math`), \\u0438 \\u0442\\u043e \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u0434\\u043b\\u044f \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u043a\\u0438 \\u043b\\u043e\\u0433\\u0438\\u043a\\u0438 \\u043f\\u0430\\u0439\\u043f\\u043b\\u0430\\u0439\\u043d\\u0430, \\u043d\\u0435 \\u043a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u0430.\\n\\n\\u041f\\u0440\\u0438\\u043e\\u0440\\u0438\\u0442\\u0435\\u0442 \\u043d\\u0435\\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0451\\u043d\\u043d\\u043e\\u0441\\u0442\\u0435\\u0439 (\\u0441\\u043c. assumptions) \\u2014 \\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\u0438\\u0447\\u043d\\u043e\\u0441\\u0442\\u0438 \\u0438 \\u0432\\u044b\\u0447\\u0438\\u0441\\u043b\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u044b\\u0439 \\u0431\\u044e\\u0434\\u0436\\u0435\\u0442; \\u043e\\u043d\\u0438 \\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u044f\\u044e\\u0442, \\u0441\\u043a\\u043e\\u043b\\u044c\\u043a\\u043e \\u0434\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442\\u043e\\u0432 \\u0438 \\u0430\\u0431\\u043b\\u044f\\u0446\\u0438\\u0439 \\u0440\\u0435\\u0430\\u043b\\u044c\\u043d\\u043e \\u043f\\u043e\\u0442\\u044f\\u043d\\u0435\\u0442 \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u0435.\", \"evidence\": \"\\u0424\\u0430\\u043a\\u0442\\u044b \\u043e\\u043a\\u0440\\u0443\\u0436\\u0435\\u043d\\u0438\\u044f (\\u0432\\u0441\\u0435 \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u043a\\u0438 \\u0443\\u0441\\u043f\\u0435\\u0448\\u043d\\u044b, \\u0432\\u044b\\u0432\\u043e\\u0434 \\u043f\\u0440\\u0438\\u0432\\u0435\\u0434\\u0451\\u043d):\\n1. `find /workspace` \\u2192 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e `/workspace/task.json`; `ls -la` \\u2192 8.0K \\u0432\\u0441\\u0435\\u0433\\u043e. \\u041a\\u043e\\u0434/\\u043a\\u043e\\u043d\\u0444\\u0438\\u0433\\u0438/\\u0434\\u0430\\u043d\\u043d\\u044b\\u0435 \\u043e\\u0442\\u0441\\u0443\\u0442\\u0441\\u0442\\u0432\\u0443\\u044e\\u0442.\\n2. `python3 --version` \\u2192 3.14.4; \\u0438\\u043c\\u043f\\u043e\\u0440\\u0442\\u044b `torch`, `numpy`, `pandas`, `sklearn` \\u2192 `ModuleNotFoundError` \\u0434\\u043b\\u044f \\u0432\\u0441\\u0435\\u0445; `pip list | grep -iE 'torch|numpy|pandas|scipy|scikit|statsmodels|tensorflow|jax'` \\u2192 \\u043f\\u0443\\u0441\\u0442\\u043e (exit=1).\\n3. \\u0421\\u0435\\u0442\\u044c: `socket.create_connection(('pypi.org',443))` \\u0438 `urllib.request.urlopen('https://pypi.org')` \\u2192 `Temporary failure in name resolution` (DNS \\u043c\\u0451\\u0440\\u0442\\u0432) \\u2192 \\u0443\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043a\\u0430 \\u043f\\u0430\\u043a\\u0435\\u0442\\u043e\\u0432 \\u043d\\u0435\\u0432\\u043e\\u0437\\u043c\\u043e\\u0436\\u043d\\u0430.\\n4. GPU: `/dev/nvidia*` \\u043d\\u0435 \\u0441\\u0443\\u0449\\u0435\\u0441\\u0442\\u0432\\u0443\\u0435\\u0442; `nproc` \\u2192 224 CPU-\\u044f\\u0434\\u0440\\u0430.\\n5. \\u0434\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442\\u044b: `find / -maxdepth 4 -iname '*ETT*' -o -iname '*traffic*csv' -o -iname '*weather*csv'` \\u2192 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u043b\\u043e\\u0436\\u043d\\u044b\\u0435 \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u043d\\u044b\\u0435 \\u0441\\u043e\\u0432\\u043f\\u0430\\u0434\\u0435\\u043d\\u0438\\u044f (libnettle, gnome-settings \\u0438 \\u0442.\\u043f.); \\u0440\\u0435\\u0430\\u043b\\u044c\\u043d\\u044b\\u0445 CSV/\\u0434\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442\\u043e\\u0432 \\u043d\\u0435\\u0442.\\n6. `task.json` \\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0430\\u0435\\u0442: \\\"Design-only task; repositories and compute are not required\\\", datasets=[], network disabled, gpu_enabled=false.\", \"assumptions\": [\"\\u041f\\u0435\\u0440\\u0438\\u043e\\u0434\\u0438\\u0447\\u043d\\u043e\\u0441\\u0442\\u044c \\u0432 \\u0431\\u0435\\u043d\\u0447\\u043c\\u0430\\u0440\\u043a\\u0430\\u0445 (ETT/Weather/Traffic/Electricity) \\u0432\\u044b\\u0432\\u043e\\u0434\\u0438\\u0442\\u0441\\u044f \\u0438\\u0437 \\u0440\\u0435\\u0433\\u0443\\u043b\\u044f\\u0440\\u043d\\u043e\\u0439 \\u0447\\u0430\\u0441\\u0442\\u043e\\u0442\\u044b \\u0434\\u0438\\u0441\\u043a\\u0440\\u0435\\u0442\\u0438\\u0437\\u0430\\u0446\\u0438\\u0438 \\u0438 timestamps (\\u0441\\u0443\\u0442\\u043e\\u0447\\u043d\\u044b\\u0439/\\u043d\\u0435\\u0434\\u0435\\u043b\\u044c\\u043d\\u044b\\u0439 \\u0446\\u0438\\u043a\\u043b\\u044b); \\u044f\\u0432\\u043d\\u0430\\u044f \\u043a\\u043e\\u043b\\u043e\\u043d\\u043a\\u0430 'period' \\u0432 \\u0434\\u0430\\u043d\\u043d\\u044b\\u0445 \\u043e\\u0442\\u0441\\u0443\\u0442\\u0441\\u0442\\u0432\\u0443\\u0435\\u0442 \\u2014 \\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\u0438\\u0447\\u043d\\u043e\\u0441\\u0442\\u0438 \\u0432 \\u0444\\u043e\\u0440\\u043c\\u0443\\u043b\\u0438\\u0440\\u043e\\u0432\\u043a\\u0435 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0438 \\u043d\\u0435 \\u0437\\u0430\\u0434\\u0430\\u043d, \\u044d\\u0442\\u043e \\u043c\\u043e\\u0451 \\u0434\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u0435 \\u043f\\u043e \\u0441\\u0442\\u0430\\u043d\\u0434\\u0430\\u0440\\u0442\\u043d\\u044b\\u043c \\u0434\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442\\u0430\\u043c.\", \"\\u0418\\u043c\\u0435\\u0435\\u0442\\u0441\\u044f \\u0432 \\u0432\\u0438\\u0434\\u0443 CycleNet (Liang et al., ICLR 2023) \\u0441 \\u043f\\u0430\\u0442\\u0442\\u0435\\u0440\\u043d-\\u0431\\u0430\\u043d\