 \\u043e\\u0441\\u0442\\u0430\\u0442\\u043e\\u0447\\u043d\\u044b\\u0445 \\u043e\\u0446\\u0435\\u043d\\u043e\\u043a \\u0431\\u0430\\u043d\\u043a\\u0430 \\u043f\\u043e \\u0444\\u0430\\u0437\\u0435; (4) \\u0444\\u0430\\u0437\\u0430 \\u0446\\u0435\\u043b\\u0438 \\u043a\\u043e\\u0434\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f \\u0424\\u0443\\u0440\\u044c\\u0435-\\u043f\\u0440\\u0438\\u0437\\u043d\\u0430\\u043a\\u0430\\u043c\\u0438 sin/cos(2\\u03c0k\\u00b7i/L), k=1..K; (5) gaiding loss \\u043f\\u0440\\u0438\\u0442\\u044f\\u0433\\u0438\\u0432\\u0430\\u0435\\u0442 per-sample \\u043e\\u0446\\u0435\\u043d\\u043a\\u0443 \\u043f\\u0430\\u0442\\u0442\\u0435\\u0440\\u043d\\u0430 \\u043a \\u0430\\u0433\\u0440\\u0435\\u0433\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u043e\\u0439.\\n\\n**\\u0418\\u043c\\u0435\\u043d\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0435 \\u0433\\u0438\\u043f\\u0435\\u0440\\u043f\\u0430\\u0440\\u0430\\u043c\\u0435\\u0442\\u0440\\u044b** (\\u0442\\u044e\\u043d \\u043f\\u043e \\u0432\\u0430\\u043b\\u0438\\u0434\\u0430\\u0446\\u0438\\u0438; \\u0442\\u0435\\u0441\\u0442 H2 \\u2014 \\u043e\\u0442\\u0434\\u0435\\u043b\\u044c\\u043d\\u043e):\\n- `L` \\u2014 \\u0434\\u043b\\u0438\\u043d\\u0430 \\u0446\\u0438\\u043a\\u043b\\u0430 (\\u00a73; \\u043a\\u0430\\u043d\\u0434\\u0438\\u0434\\u0430\\u0442\\u044b daily/weekly, \\u0432\\u044b\\u0431\\u043e\\u0440 \\u043f\\u043e val).\\n- `d` (=d_bank) \\u2014 \\u0440\\u0430\\u0437\\u043c\\u0435\\u0440\\u043d\\u043e\\u0441\\u0442\\u044c \\u043f\\u0430\\u0442\\u0442\\u0435\\u0440\\u043d\\u0430, \\u0431\\u0430\\u043d\\u043a L\\u00d7d; \\u0441\\u0435\\u0442\\u043a\\u0430 {64,128,256}.\\n- `agg \\u2208 {EMA, running-mean}`, `\\u03b2 \\u2208 {0.9, 0.99}` \\u2014 **[A1]** \\u0442\\u043e\\u0447\\u043d\\u043e\\u0435 \\u043f\\u0440\\u0430\\u0432\\u0438\\u043b\\u043e \\u0430\\u0433\\u0440\\u0435\\u0433\\u0430\\u0446\\u0438\\u0438 \\u0438\\u0437 \\u0441\\u0442\\u0430\\u0442\\u044c\\u0438 \\u0437\\u0434\\u0435\\u0441\\u044c \\u043d\\u0435 \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u044f\\u0435\\u043c\\u043e (\\u043d\\u0435\\u0442 \\u0441\\u0435\\u0442\\u0438); \\u0440\\u0435\\u0430\\u043b\\u0438\\u0437\\u0443\\u0435\\u043c \\u043a\\u0430\\u043a \\u043f\\u0430\\u0440\\u0430\\u043c\\u0435\\u0442\\u0440, \\u00ab\\u0441\\u0432\\u0435\\u0440\\u0438\\u0442\\u044c \\u0441 \\u043f\\u0435\\u0440\\u0432\\u043e\\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a\\u043e\\u043c \\u0434\\u043e \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u044f\\u00bb.\\n- `\\u03bb_guide \\u2208 {0, 0.1, 1.0}` (0 = ablation H4) \\u2014 **[A2]** \\u0432\\u0435\\u0441 \\u0438\\u0437 \\u0441\\u0442\\u0430\\u0442\\u044c\\u0438 \\u043d\\u0435 \\u0446\\u0438\\u0442\\u0438\\u0440\\u0443\\u0435\\u043c.\\n- `K` \\u2014 \\u0447\\u0438\\u0441\\u043b\\u043e \\u0433\\u0430\\u0440\\u043c\\u043e\\u043d\\u0438\\u043a, {1,2,3}.\\n- \\u0420\\u0435\\u0436\\u0438\\u043c \\u043e\\u0431\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u0438\\u044f \\u0431\\u0430\\u043d\\u043a\\u0430: batch-mean vs online EMA \\u2014 **[A3]** \\u043f\\u0430\\u0440\\u0430\\u043c\\u0435\\u0442\\u0440\\u0438\\u0437\\u0443\\u0435\\u043c.\\n- \\u041f\\u0440\\u043e\\u0447\\u0435\\u0435: lookback \\u03c4 \\u2208 {96, 512}, batch 32, Adam, lr {1e-3, 1e-4}, \\u226420 epochs, early stopping \\u043f\\u043e val (patience 5), RevIN.\\n\\u041d\\u0438\\u043a\\u0430\\u043a\\u0438\\u0445 \\u0447\\u0438\\u0441\\u043b\\u043e\\u0432\\u044b\\u0445 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u043e\\u0432 \\u0438\\u0437 \\u043e\\u0440\\u0438\\u0433\\u0438\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0439 \\u0441\\u0442\\u0430\\u0442\\u044c\\u0438 \\u0432 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d \\u043d\\u0435 \\u0432\\u043d\\u0435\\u0441\\u0435\\u043d\\u043e (\\u043d\\u0435 \\u043e\\u0442\\u043a\\u0440\\u044b\\u0432\\u0430\\u043b\\u0438).\\n\\n## 3. \\u0414\\u0430\\u043d\\u043d\\u044b\\u0435, \\u0441\\u043f\\u043b\\u0438\\u0442\\u044b, \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\n\\n**\\u0418\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\u0438\\u0447\\u043d\\u043e\\u0441\\u0442\\u0438 \\u2014 timestamps, \\u043d\\u0435 \\u043a\\u043e\\u043b\\u043e\\u043d\\u043a\\u0430 \\u00abperiod\\u00bb**: \\u0440\\u0435\\u0433\\u0443\\u043b\\u044f\\u0440\\u043d\\u043e\\u0441\\u0442\\u044c \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u044f\\u0435\\u0442\\u0441\\u044f \\u043f\\u043e \\u043c\\u0435\\u0434\\u0438\\u0430\\u043d\\u043d\\u043e\\u043c\\u0443 \\u0448\\u0430\\u0433\\u0443 \\u0394t; L = T_cycle / \\u0394t, T_cycle \\u2208 {\\u0441\\u0443\\u0442\\u043a\\u0438, \\u043d\\u0435\\u0434\\u0435\\u043b\\u044f}. \\u0420\\u0430\\u0441\\u0441\\u0447\\u0438\\u0442\\u0430\\u043d\\u043e \\u0441\\u043a\\u0440\\u0438\\u043f\\u0442\\u043e\\u043c (\\u043f\\u0440\\u0438\\u043b\\u043e\\u0436\\u0435\\u043d\\u0438\\u0435 \\u0410):\\n\\n| \\u0414\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442 | \\u0394t | L_daily | L_weekly |\\n|---|---|---|---|\\n| ETTh1/h2 | 60 \\u043c\\u0438\\u043d | 24 | 168 |\\n| ETTm1/m2 | 10 \\u043c\\u0438\\u043d | 144 | 1008 |\\n| Weather | 10 \\u043c\\u0438\\u043d | 144 | 1008 |\\n| Traffic, Electricity | 60 \\u043c\\u0438\\u043d | 24 | 168 |\\n\\n\\u0420\\u0430\\u0437\\u043c\\u0435\\u0440\\u044b/\\u0447\\u0430\\u0441\\u0442\\u043e\\u0442\\u044b \\u2014 **[A4]** \\u043f\\u0443\\u0431\\u043b\\u0438\\u0447\\u043d\\u044b\\u0435 \\u043c\\u0435\\u0442\\u0430\\u0434\\u0430\\u043d\\u043d\\u044b\\u0435, \\u0441\\u0432\\u0435\\u0440\\u044f\\u044e\\u0442\\u0441\\u044f \\u043f\\u0440\\u0438 \\u043f\\u043e\\u043b\\u0443\\u0447\\u0435\\u043d\\u0438\\u0438 CSV (\\u0437\\u0434\\u0435\\u0441\\u044c \\u0434\\u0430\\u043d\\u043d\\u044b\\u0445 \\u043d\\u0435\\u0442). \\u0421\\u043f\\u043b\\u0438\\u0442\\u044b \\u0445\\u0440\\u043e\\u043d\\u043e\\u043b\\u043e\\u0433\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0435, \\u0431\\u0435\\u0437 \\u043f\\u0435\\u0440\\u0435\\u043c\\u0435\\u0448\\u0438\\u0432\\u0430\\u043d\\u0438\\u044f \\u043e\\u043a\\u043e\\u043d: ETTh \\u2014 12/4/4 \\u043c\\u0435\\u0441.; Weather/Traffic/Electricity \\u2014 7:1:2 **[A5]**. \\u0421\\u043a\\u043e\\u043b\\u044c\\u0437\\u044f\\u0449\\u0438\\u0435 \\u043e\\u043a\\u043d\\u0430 (\\u0448\\u0430\\u0433 1; \\u0448\\u0430\\u0433 \\u03c4/2 \\u043d\\u0430 train \\u2014 \\u043e\\u043f\\u0446\\u0438\\u044f \\u044d\\u043a\\u043e\\u043d\\u043e\\u043c\\u0438\\u0438). \\u041f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b: RevIN \\u0434\\u043b\\u044f \\u0432\\u0441\\u0435\\u0445 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0435\\u0439 \\u043e\\u0434\\u0438\\u043d\\u0430\\u043a\\u043e\\u0432\\u043e.\\n\\n**\\u041c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0438 (\\u0440\\u0435\\u0448\\u0435\\u043d\\u0438\\u0435 \\u043e\\u0434\\u043d\\u043e, \\u043a\\u0430\\u043a \\u043f\\u0440\\u043e\\u0441\\u0438\\u043b\\u0438):** \\u043e\\u0441\\u043d\\u043e\\u0432\\u043d\\u0430\\u044f \\u2014 **RevIN-\\u043d\\u043e\\u0440\\u043c\\u0430\\u043b\\u0438\\u0437\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0435 MSE/MAE**, \\u0435\\u0434\\u0438\\u043d\\u044b\\u0439 \\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b \\u0434\\u043b\\u044f \\u0432\\u0441\\u0435\\u0445 \\u043c\\u0435\\u0442\\u043e\\u0434\\u043e\\u0432. \\u041e\\u0431\\u043e\\u0441\\u043d\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435: \\u0432\\u0441\\u0435 \\u0443\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0435\\u043d\\u0438\\u044f \\u2014 \\u0432\\u043d\\u0443\\u0442\\u0440\\u0435\\u043d\\u043d\\u0438\\u0435 \\u0441\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u044f, \\u043a\\u043e\\u0442\\u043e\\u0440\\u044b\\u0435 \\u043c\\u044b \\u0441\\u0430\\u043c\\u0438 \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d\\u044f\\u0435\\u043c; \\u0432 \\u0441\\u044b\\u0440\\u043e\\u043c \\u043c\\u0430\\u0441\\u0448\\u0442\\u0430\\u0431\\u0435 \\u0430\\u0433\\u0440\\u0435\\u0433\\u0430\\u0442 \\u0434\\u043e\\u043c\\u0438\\u043d\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f \\u0440\\u0430\\u0437\\u043d\\u043e\\u0440\\u0430\\u0437\\u043c\\u0435\\u0440\\u043d\\u044b\\u043c\\u0438 \\u043a\\u0430\\u043d\\u0430\\u043b\\u0430\\u043c\\u0438 (OT \\u0432 ETT, \\u043f\\u043e\\u0442\\u043e\\u043a\\u0438 Traffic). \\u0421 \\u0432\\u043d\\u0435\\u0448\\u043d\\u0438\\u043c\\u0438 \\u0442\\u0430\\u0431\\u043b\\u0438\\u0446\\u0430\\u043c\\u0438 \\u0446\\u0438\\u0444\\u0440\\u044b **\\u043e\\u0431\\u044a\\u044f\\u0432\\u043b\\u044f\\u044e\\u0442\\u0441\\u044f \\u043d\\u0435\\u0441\\u043e\\u043f\\u043e\\u0441\\u0442\\u0430\\u0432\\u0438\\u043c\\u044b\\u043c\\u0438 \\u044f\\u0432\\u043d\\u043e\\u0439 \\u043e\\u0433\\u043e\\u0432\\u043e\\u0440\\u043a\\u043e\\u0439**; \\u0432 \\u043f\\u0440\\u0438\\u043b\\u043e\\u0436\\u0435\\u043d\\u0438\\u0435 \\u2014 \\u0432\\u0442\\u043e\\u0440\\u0438\\u0447\\u043d\\u044b\\u0435 per-channel \\u0441\\u044b\\u0440\\u044b\\u0435 \\u043c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0438, \\u0447\\u0442\\u043e\\u0431\\u044b \\u043d\\u0435 \\u0441\\u043a\\u0440\\u044b\\u0432\\u0430\\u0442\\u044c \\u043c\\u0430\\u0441\\u0448\\u0442\\u0430\\u0431.\\n\\n## 4. \\u0421\\u0435\\u0442\\u043a\\u0438 \\u0441\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u0439 \\u043f\\u043e \\u0442\\u0438\\u0440\\u0430\\u043c\\n\\n### Tier A (\\u043c\\u0438\\u043d\\u0438\\u043c\\u0430\\u043b\\u044c\\u043d\\u043e \\u0434\\u043e\\u0441\\u0442\\u0430\\u0442\\u043e\\u0447\\u043d\\u044b\\u0439; \\u043e\\u0442\\u0432\\u0435\\u0447\\u0430\\u0435\\u0442 \\u043d\\u0430 H1\\u2013H5)\\n- **\\u0414\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442\\u044b: ETTh1, ETTm1** \\u2014 \\u043f\\u043e\\u043a\\u0440\\u044b\\u0442\\u0438\\u0435 \\u0434\\u0432\\u0443\\u0445 \\u043f\\u043e\\u0440\\u044f\\u0434\\u043a\\u043e\\u0432 \\u0394t, \\u0434\\u0435\\u0448\\u0451\\u0432\\u044b\\u0435 (7 \\u043a\\u0430\\u043d\\u0430\\u043b\\u043e\\u0432), \\u0432\\u044b\\u0440\\u0430\\u0436\\u0435\\u043d\\u043d\\u0430\\u044f \\u0441\\u0443\\u0442\\u043e\\u0447\\u043d\\u0430\\u044f \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\u0438\\u043a\\u0430.\\n- **\\u0413\\u043e\\u0440\\u0438\\u0437\\u043e\\u043d\\u0442\\u044b: 96 \\u0438 724** (\\u043a\\u0440\\u0430\\u044f \\u0434\\u0438\\u0430\\u043f\\u0430\\u0437\\u043e\\u043d\\u0430).\\n- **\\u041c\\u043e\\u0434\\u0435\\u043b\\u0438: seasonal naive, DLinear, CycleNet** + 3 ablation: \\u03bb_guide=0; \\u0431\\u0435\\u0437 \\u0431\\u0430\\u043d\\u043a\\u0430 (\\u0444\\u0430\\u0437\\u0430 \\u043d\\u0435 \\u043f\\u043e\\u0434\\u0430\\u0451\\u0442\\u0441\\u044f); \\u0431\\u0435\\u0437 \\u0424\\u0443\\u0440\\u044c\\u0435-\\u043a\\u043e\\u0434\\u0438\\u0440\\u043e\\u0432\\u043a\\u0438 (learned embedding). \\u041e\\u0431\\u043e\\u0441\\u043d\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435 \\u0441\\u0442\\u0440\\u043e\\u043a: seasonal naive \\u0438\\u0437\\u043e\\u043b\\u0438\\u0440\\u0443\\u0435\\u0442 \\u00ab\\u0437\\u043d\\u0430\\u043d\\u0438\\u0435 \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\u0430 \\u0431\\u0435\\u0441\\u043f\\u043b\\u0430\\u0442\\u043d\\u043e\\u00bb; DLinear \\u2014 \\u0451\\u043c\\u043a\\u043e\\u0441\\u0442\\u043d\\u043e\\u0439 \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c \\u0431\\u0435\\u0437 \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434\\u0438\\u043a\\u0438; ab\\u043b\\u044f\\u0446\\u0438\\u0438 \\u2014 \\u043f\\u043e \\u043e\\u0434\\u043d\\u043e\\u0439 \\u043d\\u0430 \\u043c\\u0435\\u0445\\u0430\\u043d\\u0438\\u0437\\u043c (H4, \\u043c\\u0435\\u0445\\u0430\\u043d\\u0438\\u0437\\u043c H3, H5).\\n- **\\u0421\\u043f\\u0435\\u0446\\u0430\\u043a\\u043a\\u043e\\u0440\\u0434\\u044b: sensitivity \\u043f\\u043e L** {L*, L\\u00b11, L\\u00b12, wrong L} (H2) \\u0438 **zero-bank inference** (H3, \\u0431\\u0435\\u0441\\u043f\\u043b\\u0430\\u0442\\u043d\\u043e \\u2014 \\u043e\\u0434\\u0438\\u043d forward).\\n- 3 \\u0441\\u0438\\u0434\\u0430 = **screening, \\u0431\\u0435\\u0437 \\u0437\\u0430\\u044f\\u0432\\u043b\\u0435\\u043d\\u0438\\u0439 \\u043e \\u0437\\u043d\\u0430\\u0447\\u0438\\u043c\\u043e\\u0441\\u0442\\u0438 \\u043f\\u043e \\u0441\\u0438\\u0434\\u0430\\u043c**; \\u0432\\u044b\\u0432\\u043e\\u0434\\u044b \\u2014 \\u043f\\u043e **paired block bootstrap** \\u043f\\u043e test-\\u043e\\u043a\\u043d\\u0430\\u043c (B=10\\u2074, \\u0431\\u043b\\u043e\\u043a\\u0438 \\u043f\\u043e \\u03c4=96 \\u2014 **[A6]**, \\u043f\\u0440\\u043e\\u0442\\u0438\\u0432 \\u0430\\u0432\\u0442\\u043e\\u043a\\u043e\\u0440\\u0440\\u0435\\u043b\\u044f\\u0446\\u0438\\u0438 \\u043e\\u043a\\u043e\\u043d). \\u0414\\u0435\\u0448\\u0451\\u0432\\u044b\\u0439 \\u0442\\u0435\\u0441\\u0442, \\u0440\\u0430\\u0437\\u043b\\u0438\\u0447\\u0430\\u044e\\u0449\\u0438\\u0439 CycleNet vs DLinear, \\u043a\\u0430\\u043a \\u0432\\u044b \\u043f\\u0440\\u043e\\u0441\\u0438\\u043b\\u0438.\\n- \\u041e\\u0446\\u0435\\u043d\\u043a\\u0430: ~80 \\u043e\\u0431\\u0443\\u0447\\u0435\\u043d\\u0438\\u0439, \\u043c\\u043e\\u0434\\u0435\\u043b\\u0438 <1.3M \\u043f\\u0430\\u0440\\u0430\\u043c\\u0435\\u0442\\u0440\\u043e\\u0432, \\u0447\\u0438\\u0441\\u0442\\u043e\\u0435 FLOP-\\u0432\\u0440\\u0435\\u043c\\u044f \\u2014 \\u0441\\u0435\\u043a\\u0443\\u043d\\u0434\\u044b/\\u043f\\u0440\\u043e\\u0433\\u043e\\u043d \\u2192 \\u0443\\u0437\\u043a\\u043e\\u0435 \\u043c\\u0435\\u0441\\u0442\\u043e \\u043d\\u0430\\u043a\\u043b\\u0430\\u0434\\u043d\\u044b\\u0435 \\u0440\\u0430\\u0441\\u0445\\u043e\\u0434\\u044b; **4\\u201313 GPU\\u00b7\\u0447** **[A7]**.\\n\\n### Tier B (\\u043f\\u043e\\u043b\\u043d\\u044b\\u0439)\\n- \\u0414\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442\\u044b +Weather +Traffic (C=862), \\u0433\\u043e\\u0440\\u0438\\u0437\\u043e\\u043d\\u044b {96,192,336,724}, +PatchTST **[A8]**, \\u043f\\u043e\\u043b\\u043d\\u044b\\u0435 5 ablation, 3 \\u0441\\u0438\\u0434\\u0430, \\u03c4=512-\\u043a\\u043e\\u043d\\u0444\\u0438\\u0433.\\n- **\\u041f\\u0440\\u043e\\u043f\\u0443\\u0441\\u043a\\u0438 \\u2014 Tier B; \\u0441\\u043e\\u0433\\u043b\\u0430\\u0441\\u0435\\u043d \\u0441 \\u0432\\u0430\\u0448\\u0438\\u043c \\u0430\\u0440\\u0433\\u0443\\u043c\\u0435\\u043d\\u0442\\u043e\\u043c \\u0438 \\u0440\\u0430\\u0437\\u0432\\u043e\\u0436\\u0443 confound'\\u044b \\u044f\\u0432\\u043d\\u043e.** H6 \\u2014 \\u043f\\u0440\\u043e \\u0432\\u0442\\u043e\\u0440\\u0438\\u0447\\u043d\\u044b\\u0439 claim (\\u0440\\u043e\\u0431\\u0430\\u0441\\u0442\\u043d\\u043e\\u0441\\u0442\\u044c), \\u043d\\u0435 \\u043f\\u0440\\u043e \\u044f\\u0434\\u0440\\u043e (H1\\u2013H3 \\u043d\\u0430 \\u0446\\u0435\\u043b\\u044b\\u0445 \\u0431\\u0435\\u043d\\u0447\\u043c\\u0430\\u0440\\u043a\\u0430\\u0445), \\u0438 \\u043c\\u0435\\u0445\\u0430\\u043d\\u0438\\u0437\\u043c missing \\u2014 \\u043e\\u0442\\u0434\\u0435\\u043b\\u044c\\u043d\\u044b\\u0439 \\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a \\u0437\\u0430\\u043c\\u0435\\u0448\\u0438\\u0432\\u0430\\u043d\\u0438\\u044f:\\n  - \\u041c\\u0435\\u0445\\u0430\\u043d\\u0438\\u0437\\u043c\\u044b: **MCAR-\\u043f\\u043e-\\u0442\\u043e\\u0447\\u043a\\u0430\\u043c** (\\u03c1 \\u2208 {10,30,50}%, \\u043f\\u043e\\u043a\\u0440\\u044b\\u0442\\u0438\\u0435 \\u0444\\u0430\\u0437 \\u0441\\u043e\\u0445\\u0440\\u0430\\u043d\\u044f\\u0435\\u0442\\u0441\\u044f) vs **block-missing** (\\u0431\\u043b\\u043e\\u043a\\u0438 \\u2265 L/4 \\u0438 \\u043e\\u0434\\u0438\\u043d \\u0446\\u0435\\u043b\\u044b\\u043c \\u0446\\u0438\\u043a\\u043b\\u043e\\u043c; \\u043b\\u043e\\u043a\\u0430\\u043b\\u044c\\u043d\\u043e \\u043f\\u0430\\u0434\\u0430\\u0435\\u0442 \\u043f\\u043e\\u043a\\u0440\\u044b\\u0442\\u0438\\u0435 \\u0444\\u0430\\u0437 \\u2014 \\u043b\\u043e\\u043c\\u0430\\u0435\\u0442\\u0441\\u044f \\u0441\\u0430\\u043c\\u0430 \\u0444\\u0430\\u0437\\u043e\\u0432\\u0430\\u044f \\u0430\\u0433\\u0440\\u0435\\u0433\\u0430\\u0446\\u0438\\u044f).\\n  - \\u0420\\u0430\\u0437\\u0432\\u043e\\u0434\\u043a\\u0430: \\u0432 \\u043a\\u0430\\u0436\\u0434\\u043e\\u0439 \\u044f\\u0447\\u0435\\u0439\\u043a\\u0435 \\u043c\\u0435\\u0445\\u0430\\u043d\\u0438\\u0437\\u043c\\u00d7\\u03c1 \\u0440\\u0435\\u043f\\u043e\\u0440\\u0442\\u0438\\u043c **\\u043f\\u043e\\u043a\\u0440\\u044b\\u0442\\u0438\\u0435 \\u0444\\u0430\\u0437** (\\u0434\\u043e\\u043b\\u044f \\u0444\\u0430\\u0437 \\u0441 \\u22651 \\u043d\\u0430\\u0431\\u043b\\u044e\\u0434\\u0435\\u043d\\u0438\\u0435\\u043c \\u0432 \\u043a\\u043e\\u043d\\u0442\\u0435\\u043a\\u0441\\u0442\\u043d\\u043e\\u043c \\u043e\\u043a\\u043d\\u0435) \\u043a\\u0430\\u043a \\u043a\\u043e\\u0432\\u0430\\u0440\\u0438\\u0430\\u0442\\u0443; \\u043a\\u0440\\u0438\\u0432\\u044b\\u0435 \\u0434\\u0435\\u0433\\u0440\\u0430\\u0434\\u0430\\u0446\\u0438\\u0438 \\u2014 \\u0440\\u0430\\u0437\\u0434\\u0435\\u043b\\u044c\\u043d\\u043e \\u043f\\u043e \\u043c\\u0435\\u0445\\u0430\\u043d\\u0438\\u0437\\u043c\\u0430\\u043c, \\u0441\\u043c\\u0435\\u0448\\u0438\\u0432\\u0430\\u0442\\u044c \\u0432 \\u043e\\u0434\\u043d\\u0443 \\u0441\\u0442\\u0440\\u043e\\u043a\\u0443 \\u0437\\u0430\\u043f\\u0440\\u0435\\u0449\\u0435\\u043d\\u043e \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d-\\u043f\\u0440\\u0430\\u0432\\u0438\\u043b\\u043e\\u043c. \\u041e\\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u0436\\u0435\\u043d\\u0438\\u0435 H6 \\u043f\\u0440\\u0435\\u0434\\u0437\\u0430\\u0434\\u0430\\u043d\\u043e \\u0432 \\u00a71.\\n  - \\u0421\\u0432\\u043e\\u044f baseline-\\u0441\\u0435\\u0442\\u043a\\u0430: seasonal naive, DLinear, PatchTST, CycleNet (full \\u0438 \\u0431\\u0435\\u0437 gaiding loss \\u2014 \\u0435\\u0441\\u043b\\u0438 \\u0440\\u043e\\u0431\\u0430\\u0441\\u0442\\u043d\\u043e\\u0441\\u0442\\u044c \\u0434\\u0430\\u0451\\u0442 gaiding-\\u0447\\u043b\\u0435\\u043d, \\u0432\\u0438\\u0434\\u043d\\u043e \\u0437\\u0434\\u0435\\u0441\\u044c).\\n- \\u041e\\u0446\\u0435\\u043d\\u043a\\u0430: \\u0434\\u043e\\u043c\\u0438\\u043d\\u0430\\u043d\\u0442\\u0430 \\u2014 PatchTST \\u043d\\u0430 Traffic: **48\\u2013192 GPU\\u00b7\\u0447**; \\u0432\\u0435\\u0441\\u044c Tier B \\u2014 **\\u043f\\u043e\\u0440\\u044f\\u0434\\u043a\\u0430 150\\u2013400 GPU\\u00b7\\u0447** **[A7][A9]**.\\n\\n## 5. \\u0427\\u0442\\u043e \\u043d\\u0435\\u043b\\u044c\\u0437\\u044f \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u0438\\u0442\\u044c \\u0432 \\u0442\\u0435\\u043a\\u0443\\u0449\\u0435\\u043c sandbox (\\u0432\\u0435\\u0440\\u0438\\u0444\\u0438\\u0446\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043e)\\n\\n1. \\u0423\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043a\\u0443 torch/numpy/pandas \\u2014 DNS \\u043c\\u0451\\u0440\\u0442\\u0432, pip \\u043d\\u0435\\u0434\\u043e\\u0441\\u0442\\u0443\\u043f\\u0435\\u043d.\\n2. \\u041f\\u043e\\u043b\\u0443\\u0447\\u0435\\u043d\\u0438\\u0435 CSV \\u0431\\u0435\\u043d\\u0447\\u043c\\u0430\\u0440\\u043a\\u043e\\u0432 \\u2014 \\u0441\\u0435\\u0442\\u0438 \\u043d\\u0435\\u0442; \\u0434\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442\\u043e\\u0432 \\u043d\\u0430 \\u0424\\u0421 \\u043d\\u0435\\u0442.\\n3. \\u041b\\u044e\\u0431\\u043e\\u0435 \\u043e\\u0431\\u0443\\u0447\\u0435\\u043d\\u0438\\u0435/\\u0438\\u043d\\u0444\\u0435\\u0440\\u0435\\u043d\\u0441 \\u2014 \\u043d\\u0435\\u0442 \\u043f\\u0430\\u043a\\u0435\\u0442\\u043e\\u0432 \\u0438 GPU; CPU-only \\u0431\\u0435\\u0437 numpy \\u043d\\u0435 \\u0437\\u0430\\u043f\\u0443\\u0441\\u043a\\u0430\\u0435\\u043c\\u043e.\\n4. \\u0421\\u0432\\u0435\\u0440\\u043a\\u0443 [A1\\u2013A3] \\u0441 \\u043f\\u0435\\u0440\\u0432\\u043e\\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a\\u043e\\u043c \\u0438 [A4] \\u0441 \\u0444\\u0430\\u043a\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u043c\\u0438 \\u0444\\u0430\\u0439\\u043b\\u0430\\u043c\\u0438 \\u2014 \\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442 \\u0441\\u0435\\u0442\\u0438/\\u0434\\u0430\\u043d\\u043d\\u044b\\u0445.\\n\\u0421\\u043b\\u0435\\u0434\\u0441\\u0442\\u0432\\u0438\\u0435: \\u0434\\u043e\\u043a\\u0443\\u043c\\u0435\\u043d\\u0442 \\u0441\\u0430\\u043c\\u043e\\u0434\\u043e\\u0441\\u0442\\u0430\\u0442\\u043e\\u0447\\u0435\\u043d \\u0434\\u043b\\u044f \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u044f \\u0432\\u043d\\u0435 sandbox; \\u0437\\u0434\\u