P. \\u0418\\u0442\\u043e\\u0433: **Tier A \\u2248 4\\u201313 GPU\\u00b7\\u0447, Tier B \\u2248 150\\u2013400 GPU\\u00b7\\u0447** (\\u0434\\u043e\\u043c\\u0438\\u043d\\u0430\\u043d\\u0442\\u0430 \\u2014 \\u0442\\u0440\\u0430\\u043d\\u0441\\u0444\\u043e\\u0440\\u043c\\u0435\\u0440-\\u043b\\u0438\\u043d\\u0438\\u044f \\u043d\\u0430 Traffic).\\n\\n## \\u0414\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u044f (\\u0441\\u0432\\u043e\\u0434\\u043d\\u043e)\\n[A1] \\u043f\\u0440\\u0430\\u0432\\u0438\\u043b\\u043e \\u0430\\u0433\\u0440\\u0435\\u0433\\u0430\\u0446\\u0438\\u0438 \\u0431\\u0430\\u043d\\u043a\\u0430 (EMA/mean, \\u03b2) \\u2014 \\u0441\\u0432\\u0435\\u0440\\u0438\\u0442\\u044c \\u0441 \\u043f\\u0435\\u0440\\u0432\\u043e\\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a\\u043e\\u043c; [A2] \\u03bb_guide \\u2014 \\u0441\\u0435\\u0442\\u043a\\u0430, \\u043d\\u0435 \\u0446\\u0438\\u0444\\u0440\\u0430 \\u0438\\u0437 \\u0441\\u0442\\u0430\\u0442\\u044c\\u0438; [A3] \\u0440\\u0435\\u0436\\u0438\\u043c \\u043e\\u0431\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u0438\\u044f \\u0431\\u0430\\u043d\\u043a\\u0430; [A4] \\u0441\\u0442\\u0440\\u043e\\u043a\\u0438/\\u043a\\u0430\\u043d\\u0430\\u043b\\u044b/\\u0447\\u0430\\u0441\\u0442\\u043e\\u0442\\u044b \\u0434\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442\\u043e\\u0432 \\u2014 \\u043f\\u0443\\u0431\\u043b\\u0438\\u0447\\u043d\\u044b\\u0435 \\u043c\\u0435\\u0442\\u0430\\u0434\\u0430\\u043d\\u043d\\u044b\\u0435, \\u0441\\u0432\\u0435\\u0440\\u044f\\u044e\\u0442\\u0441\\u044f \\u043f\\u0440\\u0438 \\u0432\\u044b\\u0433\\u0440\\u0443\\u0437\\u043a\\u0435; [A5] \\u0433\\u0440\\u0430\\u043d\\u0438\\u0446\\u044b \\u0441\\u043f\\u043b\\u0438\\u0442\\u043e\\u0432 \\u043f\\u043e \\u043a\\u043e\\u043d\\u0432\\u0435\\u043d\\u0446\\u0438\\u0438 \\u0441\\u0442\\u0430\\u043d\\u0434\\u0430\\u0440\\u0442\\u043d\\u044b\\u0445 \\u0440\\u0435\\u043f\\u043e\\u0437\\u0438\\u0442\\u043e\\u0440\\u0438\\u0435\\u0432; [A6] \\u0434\\u043b\\u0438\\u043d\\u0430 \\u0431\\u043b\\u043e\\u043a\\u0430 bootstrap = \\u03c4; [A7] wall-clock 3\\u201310 \\u043c\\u0438\\u043d/\\u043c\\u0430\\u043b\\u044b\\u0439 \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d \\u0438 throughput 10\\u00b9\\u00b2 FLOP/s \\u2014 \\u0438\\u043d\\u0436\\u0435\\u043d\\u0435\\u0440\\u043d\\u044b\\u0435 \\u043e\\u0446\\u0435\\u043d\\u043a\\u0438 \\u043f\\u043e\\u0440\\u044f\\u0434\\u043a\\u0430, \\u043d\\u0435 \\u0438\\u0437\\u043c\\u0435\\u0440\\u0435\\u043d\\u0438\\u044f; [A8] \\u0432\\u044b\\u0431\\u043e\\u0440 PatchTST \\u043a\\u0430\\u043a \\u0442\\u0440\\u0430\\u043d\\u0441\\u0444\\u043e\\u0440\\u043c\\u0435\\u0440-\\u043b\\u0438\\u043d\\u0438\\u0438; [A9] \\u00ab\\u0442\\u044f\\u0436\\u0435\\u0441\\u0442\\u044c\\u00bb \\u0442\\u0440\\u0430\\u043d\\u0441\\u0444\\u043e\\u0440\\u043c\\u0435\\u0440\\u0430 \\u043d\\u0430 Traffic 2\\u20138 GPU\\u00b7\\u0447/\\u043f\\u0440\\u043e\\u0433\\u043e\\u043d; [A10] \\u043f\\u0440\\u0435\\u0434\\u043f\\u043e\\u043b\\u0430\\u0433\\u0430\\u0435\\u043c\\u044b\\u0439 \\u044d\\u0444\\u0444\\u0435\\u043a\\u0442\\u0438\\u0432\\u043d\\u044b\\u0439 GPU-throughput. \\u041d\\u0438 \\u043e\\u0434\\u043d\\u0430 \\u0433\\u0438\\u043f\\u043e\\u0442\\u0435\\u0437\\u0430 \\u043d\\u0435 \\u0437\\u0430\\u0432\\u0438\\u0441\\u0438\\u0442 \\u043e\\u0442 [A7\\u2013A10] \\u2014 \\u043e\\u043d\\u0438 \\u0432\\u043b\\u0438\\u044f\\u044e\\u0442 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u043d\\u0430 \\u0431\\u044e\\u0434\\u0436\\u0435\\u0442.\", \"evidence\": \"1) \\u041e\\u0441\\u043c\\u043e\\u0442\\u0440 \\u043e\\u043a\\u0440\\u0443\\u0436\\u0435\\u043d\\u0438\\u044f (\\u0432\\u0435\\u0440\\u0438\\u0444\\u0438\\u0446\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043e \\u043f\\u0440\\u0435\\u0434\\u044b\\u0434\\u0443\\u0449\\u0438\\u043c \\u0445\\u043e\\u0434\\u043e\\u043c): /workspace \\u0441\\u043e\\u0434\\u0435\\u0440\\u0436\\u0438\\u0442 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e task.json; torch/numpy/pandas/sklearn \\u043e\\u044